LEVEL = 1
CFG = {1: 3, 2: 5, 3: 8}
log = [{"entry": i, "sealed": True} for i in range(CFG[LEVEL])]
def write(i, data):
    if log[i]["sealed"]:
        return "REJECTED: entry sealed"
    log[i]["data"] = data
    return "written"
print(write(0, "changed"), "| entries:", len(log), "| all sealed:", all(e["sealed"] for e in log))

